def kthTermAcross(seqs, k):
    def count(x):
        total = 0
        for s, d in seqs:
            if x >= s:
                total += (x - s) // d + 1
        return total

    lo, hi = 1, 2 * 10 ** 9
    while lo < hi:
        mid = (lo + hi) // 2
        if count(mid) >= k:
            hi = mid
        else:
            lo = mid + 1
    return lo
